const elementOverrides = process.env.E2E_NAV_ELEMENT_ICONS
if (elementOverrides) {
  const overrideMap = JSON.parse(elementOverrides)
  await page.evaluate((icons) => {
    for (const [title, key] of Object.entries(icons)) {
      const item = [...document.querySelectorAll('.top-nav .nav-item')]
        .find((entry) => entry.querySelector('.nav-text')?.textContent.trim() === title)
      const icon = item?.querySelector('.nav-item__icon')
      if (!icon || icon.tagName.toLowerCase() !== 'i') continue
      icon.className = `nav-item__icon nav-item__icon--element el-icon-${key}`
    }
  }, overrideMap)
  console.log(`[navbar-visual] Element overrides=${Object.keys(overrideMap).length}`)
}
const spriteOverrides = process.env.E2E_NAV_SPRITE_ICONS
if (spriteOverrides) {
  const overrideMap = JSON.parse(spriteOverrides)
  await page.evaluate((icons) => {
    const svgNamespace = 'http://www.w3.org/2000/svg'
    const xlinkNamespace = 'http://www.w3.org/1999/xlink'
    for (const [title, key] of Object.entries(icons)) {
      const item = [...document.querySelectorAll('.top-nav .nav-item')]
        .find((entry) => entry.querySelector('.nav-text')?.textContent.trim() === title)
      const previousIcon = item?.querySelector('.nav-item__icon')
      if (!previousIcon) continue
      const svg = document.createElementNS(svgNamespace, 'svg')
      svg.setAttribute('class', 'nav-item__icon')
      svg.setAttribute('aria-hidden', 'true')
      const use = document.createElementNS(svgNamespace, 'use')
      use.setAttribute('fill', 'none')
      use.setAttribute('stroke', 'currentColor')
      use.setAttribute('stroke-width', '1.7')
      use.setAttribute('stroke-linecap', 'round')
      use.setAttribute('stroke-linejoin', 'round')
      use.setAttributeNS(xlinkNamespace, 'xlink:href', `#navbar-icon-${key}`)
      use.setAttribute('href', `#navbar-icon-${key}`)
      svg.appendChild(use)
      previousIcon.replaceWith(svg)
    }
  }, overrideMap)
  console.log(`[navbar-visual] sprite overrides=${Object.keys(overrideMap).length}`)
}
const visualCss = process.env.E2E_NAV_TEST_CSS
if (visualCss) {
  await page.addStyleTag({ content: visualCss })
  console.log('[navbar-visual] custom CSS override applied')
}
await page.evaluate(() => document.fonts.ready.then(() => true))
const sourceFontLoaded = await page.evaluate(() => document.fonts.check('14px SourceHanSansCN-Regular'))
console.log(`[navbar-visual] SourceHanSansCN-Regular loaded=${sourceFontLoaded}`)
